178:       checkNotNull(event);
179:       while (subscribers.hasNext()) {
180:         queue.add(new EventWithSubscriber(event, subscribers.next()));
181:       }
182: 
183:       EventWithSubscriber e;
184:       while ((e = queue.poll()) != null) {
185:         e.subscriber.dispatchEvent(e.event);
186:       }
187:     }
